import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, uv, positionLocal, vec3, uniform, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE, primitives } = { THREE: ctx.THREE, primitives: ctx.primitives };
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight, Texture } = THREE;

  const palette = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'pricing-list-row';

  const ROW_W = 3.0;
  const ROW_H = 0.55;

  // ---------------------------------------------------------------
  // Placeholder textures (swapped once real assets resolve)
  // ---------------------------------------------------------------
  const imgPlaceholder = new Texture();
  const depthPlaceholder = new Texture();

  const imgTexNode = texture(imgPlaceholder, uv());
  const depthTexNode = texture(depthPlaceholder, uv());

  const textureLoadedUniform = uniform(0.0);
  const displacementAmount = uniform(0.02);

  // ---------------------------------------------------------------
  // Row surface — tessellated plane, machined-metal PBR
  // ---------------------------------------------------------------
  const rowGeo = new PlaneGeometry(ROW_W, ROW_H, 64, 64);
  const rowMat = new MeshStandardNodeMaterial({
    metalness: 0.45,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4,
  });

  const gradientNode = mix(color(palette.surface), color(palette.ink), uv().y);
  rowMat.colorNode = mix(gradientNode, imgTexNode, textureLoadedUniform);

  const depthDisplace = depthTexNode.r.mul(displacementAmount).mul(textureLoadedUniform);
  rowMat.positionNode = positionLocal.add(vec3(0.0, 0.0, depthDisplace));

  const rowMesh = new Mesh(rowGeo, rowMat);
  rowMesh.name = 'row-surface';
  root.add(rowMesh);

  // ---------------------------------------------------------------
  // Divider — subtle line beneath the row
  // ---------------------------------------------------------------
  const dividerGeo = new BoxGeometry(ROW_W * 0.94, 0.006, 0.006);
  const dividerMat = new MeshStandardNodeMaterial({
    roughness: 0.7,
    metalness: 0.1,
    transparent: true,
    opacity: 0.35,
  });
  dividerMat.colorNode = color(palette.paper);
  const divider = new Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -ROW_H * 0.42, 0.01);
  divider.name = 'row-divider';
  root.add(divider);

  // ---------------------------------------------------------------
  // Accent rim light (opposite the key, low intensity, accent hue)
  // ---------------------------------------------------------------
  const rimLight = new DirectionalLight(new THREE.Color(palette.accent), 0.7);
  rimLight.position.set(-1.2, 0.6, 1.4);
  root.add(rimLight);

  // ---------------------------------------------------------------
  // Text content — render ONLY what the spec provides, verbatim
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textNodes = [];

  for (const item of items) {
    if (!item?.text) continue;
    const isMeta = /meta|caption|label/i.test(item.role ?? '');
    const fontSizePx = item.typography?.fontSize ?? (isMeta ? 20 : 30);
    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize: fontSizePx,
      color: isMeta ? palette.paper : palette.paper,
      align: isMeta ? 'right' : 'left',
      maxWidthPx: 900,
    });
    const scaleFactor = 0.0075;
    textObj.scale.setScalar(scaleFactor);
    textObj.position.set(
      isMeta ? ROW_W * 0.5 - 0.15 : -ROW_W * 0.5 + 0.15,
      0.03,
      0.02
    );
    textObj.name = isMeta ? 'row-meta' : 'row-title';
    root.add(textObj);
    textNodes.push(textObj);
  }

  // ---------------------------------------------------------------
  // Async asset resolution
  // ---------------------------------------------------------------
  let loadedImgTex = null;
  let loadedDepthTex = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedImgTex = tex;
      imgTexNode.value = tex;
      textureLoadedUniform.value = 1.0;
    });
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      loadedDepthTex = tex;
      depthTexNode.value = tex;
    });
  }

  // ---------------------------------------------------------------
  // Cinematic primitives — applied verbatim from config
  // ---------------------------------------------------------------
  const primitiveHandles = [];
  for (const prim of config.cinematicPrimitives ?? []) {
    const fn = primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(root, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---------------------------------------------------------------
  // Entrance — weighted-settle + rise-in
  // ---------------------------------------------------------------
  const baseY = root.position.y;
  root.scale.setScalar(0.96);
  root.position.y = baseY + 0.3;

  const entryTl = gsap.timeline();
  entryTl.to(root.position, { y: baseY, duration: 0.7, ease: 'power3.out' }, 0);
  entryTl.to(root.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.45, ease: 'power2.out' }, 0);
  entryTl.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.45, ease: 'power4.out' }, 0.45);

  // ---------------------------------------------------------------
  // Interaction handlers
  // ---------------------------------------------------------------
  root.userData.handlers = {
    hover: (isEntering) => {
      gsap.killTweensOf(root.position);
      gsap.to(root.position, {
        y: isEntering ? baseY + 0.15 : baseY,
        duration: 0.3,
        ease: 'power2.out',
      });
    },
    click: () => {
      gsap.killTweensOf(root.scale);
      gsap.to(root.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(2)',
        yoyo: true,
        repeat: 1,
      });
      ctx.emit('hub-pricing.select', { id: config.id ?? 'hub-pricing-row' });
    },
  };

  // ---------------------------------------------------------------
  // Cleanup
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    entryTl.kill();
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.scale);

    for (const handle of primitiveHandles) {
      handle?.timeline?.kill?.();
      handle?.cleanup?.();
    }

    rowGeo.dispose();
    rowMat.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();

    imgPlaceholder.dispose();
    depthPlaceholder.dispose();
    if (loadedImgTex) loadedImgTex.dispose();
    if (loadedDepthTex) loadedDepthTex.dispose();

    for (const t of textNodes) {
      t.traverse?.((child) => {
        child.geometry?.dispose?.();
        child.material?.dispose?.();
      });
    }

    rimLight.dispose?.();
  };

  return root;
}
